// Wards grouped by constituency, in original order — handy for a grouped dropdown/list UI.
export function getWardsByConstituency() {
  const map = new Map();
  for (const w of wards) {
    if (!map.has(w.constituency)) map.set(w.constituency, []);
    map.get(w.constituency).push(w);
  }
  return Array.from(map.entries()).map(([constituency, list]) => ({ constituency, wards: list }));
}

export function findWard(wardNo, constituency) {
  return wards.find((w) => w.wardNo === wardNo && (!constituency || w.constituency === constituency));
}